from h34 import *
M=mcq;F=tf;S=short;N=num
b='<text x="360" y="26" text-anchor="middle" font-size="18" font-weight="bold">15 × 14 by splitting into tens and ones</text>'
b+='<rect x="120" y="60" width="300" height="200" fill="#cfe8f3" stroke="#222" stroke-width="2"/><rect x="420" y="60" width="120" height="200" fill="#fde7b0" stroke="#222" stroke-width="2"/>'
b+='<rect x="120" y="260" width="300" height="100" fill="#d4efd0" stroke="#222" stroke-width="2"/><rect x="420" y="260" width="120" height="100" fill="#f6c8d0" stroke="#222" stroke-width="2"/>'
b+='<text x="270" y="165" text-anchor="middle" font-size="20">10 × 10 = 100</text><text x="480" y="165" text-anchor="middle" font-size="20">10 × 4 = 40</text><text x="270" y="315" text-anchor="middle" font-size="20">5 × 10 = 50</text><text x="480" y="315" text-anchor="middle" font-size="20">5 × 4 = 20</text>'
b+='<text x="270" y="50" text-anchor="middle">10</text><text x="480" y="50" text-anchor="middle">4</text><text x="100" y="165" text-anchor="end">10</text><text x="100" y="315" text-anchor="end">5</text>'
